    if (P.child && P.child.state === 0xff) P.child = null;                // its unit gone (not in states 1 / 2)
    if (P.type === 3 && P.child){ endChild(P.child, out); P.child = null; }   // +0x1640 == 3: its vtable +0x148(0)
