    if (!def){ if (S.base === 'base02g') out.refused.push({ beam: S.type && S.type.id, why: 'hunter pass: the beam type has no folder / hit 0 (render/beam-types.js; base02 registers slot 0 from hit 0, 0x3fbab0)' }); continue; }
