function spawn061(state, D, a, ctx, input, out, fresh){
  if (fresh || !state.hist || !state.prevJoints) return;
  const own = ctx.own001, J = state.prevJoints;
  for (const sp of a.spawns){
    if (!pass001(state, f(sp.frame))) continue;
    const def = D.shells[sp.shell];
    if (!def.modes[sp.mode]) continue;                   // a mode the file does not carry (Duramboros's 7 / 8): nothing made
    const why = missing001(own, { facing: true, floor: sp.shell === 'shell19' });
    if (why){ out.refused.push({ action: a.action, shell: sp.shell, mode: sp.mode, why }); continue; }
    const S = sp.shell === 'shell19'
      ? (def.id === 0x10b ? make061s19v4(state, D, sp.mode, J, own, ctx, a.action, sp.frame, null) : make061s19(state, D, sp.mode, J, own, ctx, a.action, sp.frame))
      : make00n(state, D, sp.mode, J, Object.assign({}, own, { requestPos: [0, 0, 0], requestAngles: [0, 0, 0] }), ctx, a.action, sp.frame);
    if (S){ state.shells.push(S); out.spawned.push(S); }
  }
}
// ---- RUSTRUM DURAMBOROS (em061_04): uEm061_00 at variant 4 -------------------------------------------------------------------
// READ 2026-10-18 (dev/rom-map.md "Fanged Beasts -- the shells", the em061 rows; dev/em061-shells-spec.md). His ids (vt+0x158
// 0xf23ec0, variant 4): +0xcac8 0x108 sp_00, +0xcacc 0x109 sp_01, +0xcad0 0x10a sp_13, +0xcad4 0x10b sp_19, +0xcad8 0x10c sp_24.
