  return { joint: I(0), flags: I(1) !== -1 ? 1 : 0, gravity: F(0), near: F(1), far: F(2), life: F(3), scale: F(4), speed: F(5),
           solveG: F(6), vec: (sh.vecs[0] || ZERO3).map(f), turn: sh.vecs[1] ? sh.vecs[1].map(f) : null };
