    if (!(flags & 1)) o = [mla(mla(f(M[4] * y), M[0], x), M[8], z), mla(mla(f(y * M[5]), x, M[1]), z, M[9]), mla(mla(f(y * M[6]), x, M[2]), z, M[10])];
