      const s6 = mls(f(cs * f(445.0)), sn, f(0.0)), s8 = mla(f(cs * f(0.0)), sn, f(445.0));
      const pt = [mla(P[0], sz, s8), mla(P[1], sz, f(-300.0)), mla(P[2], sz, s6)];
