  // the hold) -- the play's first wrap here; a replay of the clip is a new play, armed again
  const wrapNow = ctx.wrapped && !!state.webArmed088;
  if (wrapNow) state.webArmed088 = false;
  if (fresh) state.webArmed088 = true;
