      if (!own.target){ out.refused.push({ action: a.action, shell: 'shell57', why: 'no target (input.rock.target): the throw aims at block +0x1d0' }); continue; }
      req = { k: carry, mode: carry, placement: 1, behaviour: 1, trail: 1 };
